{
  "name": "电动位移执行器",
  "name_en": "Motorized Positioning Actuator",
  "manufacturer": "",
  "description": "一种用于实验室自动定位与扫描的电动运动装置，可驱动样品、探头或光学元件沿一个或多个轴进行绝对移动、相对移动、回零和停止，并返回当前位置与轴信息。常见形式包括电动位移台、旋转台或其他机电执行器，常用于对准、扫描和自动化测量。",
  "description_en": "A motorized motion device used for laboratory positioning and scanning. It can move samples, probes, or optical components along one or more axes with absolute moves, relative moves, homing, and stop control, while reporting current position and axis information. Typical examples include motorized translation stages, rotation stages, and other electromechanical actuators used for alignment, scanning, and automated measurements.",
  "tag_hints": [
    "motorized motion control",
    "positioning actuator",
    "translation stage",
    "rotation stage",
    "absolute and relative move",
    "position feedback",
    "laboratory automation"
  ],
  "actions": [
    {
      "action_name": "auto-process_ui_cmds",
      "description": "处理执行器控制命令",
      "description_en": "Process actuator control commands."
    },
    {
      "action_name": "auto-master",
      "description": "获取/设置主从状态",
      "description_en": "Get/set the master-slave status."
    },
    {
      "action_name": "auto-append_data",
      "description": "追加记录当前位置或状态数据",
      "description_en": "Append current position or status data."
    },
    {
      "action_name": "auto-stop_motion",
      "description": "停止当前运动",
      "description_en": "Stop current motion."
    },
    {
      "action_name": "auto-move",
      "description": "执行通用移动命令",
      "description_en": "Execute a generic motion command."
    },
    {
      "action_name": "auto-move_abs",
      "description": "移动到绝对位置",
      "description_en": "Move to an absolute position."
    },
    {
      "action_name": "auto-move_home",
      "description": "移动到原点位置",
      "description_en": "Move to the home position."
    },
    {
      "action_name": "auto-move_rel",
      "description": "按相对位移移动",
      "description_en": "Move by a relative offset."
    },
    {
      "action_name": "auto-move_rel_p",
      "description": "按预设正方向步进移动",
      "description_en": "Move by a preset positive step."
    },
    {
      "action_name": "auto-move_rel_m",
      "description": "按预设负方向步进移动",
      "description_en": "Move by a preset negative step."
    },
    {
      "action_name": "auto-quit_fun",
      "description": "关闭并释放执行器",
      "description_en": "Close and deinitialize the actuator."
    },
    {
      "action_name": "auto-init_hardware",
      "description": "初始化/反初始化执行器硬件",
      "description_en": "Initialize or deinitialize the actuator hardware."
    },
    {
      "action_name": "auto-value_changed",
      "description": "应用设置值变更",
      "description_en": "Apply a changed setting value."
    },
    {
      "action_name": "auto-setup_continuous_saving",
      "description": "配置连续位置数据保存",
      "description_en": "Configure continuous saving of position data."
    },
    {
      "action_name": "auto-param_deleted",
      "description": "删除一个配置参数",
      "description_en": "Delete a configuration parameter."
    },
    {
      "action_name": "auto-child_added",
      "description": "添加一个配置参数",
      "description_en": "Add a configuration parameter."
    },
    {
      "action_name": "auto-raise_timeout",
      "description": "标记通信或运动超时",
      "description_en": "Flag a communication or motion timeout."
    },
    {
      "action_name": "auto-thread_status",
      "description": "处理执行器返回的状态信息",
      "description_en": "Process status information returned by the actuator."
    },
    {
      "action_name": "auto-grab",
      "description": "开始轮询当前位置",
      "description_en": "Start polling the current position."
    },
    {
      "action_name": "auto-stop_grab",
      "description": "停止位置轮询",
      "description_en": "Stop position polling."
    },
    {
      "action_name": "auto-actuator",
      "description": "获取/设置所选执行器类型",
      "description_en": "Get/set the selected actuator type."
    },
    {
      "action_name": "auto-update_plugin_config",
      "description": "更新执行器配置",
      "description_en": "Update the actuator configuration."
    },
    {
      "action_name": "auto-units",
      "description": "获取/设置运动单位",
      "description_en": "Get/set the motion units."
    },
    {
      "action_name": "auto-axis_name",
      "description": "获取/设置当前轴名称",
      "description_en": "Get/set the current axis name."
    },
    {
      "action_name": "auto-update_settings",
      "description": "更新控制设置",
      "description_en": "Update control settings."
    },
    {
      "action_name": "auto-connect_tcp_ip",
      "description": "通过TCP/IP连接执行器控制器",
      "description_en": "Connect the actuator controller via TCP/IP."
    },
    {
      "action_name": "auto-connect_leco",
      "description": "连接/断开LECO通信",
      "description_en": "Connect or disconnect LECO communication."
    },
    {
      "action_name": "auto-process_tcpip_cmds",
      "description": "处理来自TCP/IP的控制命令",
      "description_en": "Process control commands received over TCP/IP."
    }
  ]
}

